# Edit a person on a sheet. Validate first so a blank name or a bad grade is a 400, not a 404.
# A name another person on the sheet already has is a 409. An edit made from a version of the person
# someone else has since saved over is a 412.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: version
version:
  class: net.officefloor.hq.app.person.CheckPersonVersion
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.ApplyPerson
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.person.CheckPersonName
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.person.AuditPersonEdited
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# Open the selected claims together, in list order. Each that cannot be opened is refused and left
# as it is; the response tells how many were opened and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: open
# Each claim opened is audited as it is opened: its own line, then the figures it moved.
open:
  class: net.officefloor.hq.app.claim.OpenSelectedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body)
            throws InvalidPersonException {
        String name = PersonRequest.checkName(request == null ? null : request.name());
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) throw new InvalidPersonException("A grade is one of A, B or C");
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("A from-date is a date, yyyy-MM-dd");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
            throw new InvalidPersonException("Terms are a whole number of days, 0 or more, or blank");
        }
        if (!terms.isEmpty()) terms = String.valueOf(Integer.parseInt(terms));
        body.set(new PersonRequest(name, grade, request.version(), gradeFrom, terms));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("personId") String personId, @Val Sheet sheet,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Person person = null;
        try {
            person = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (person == null) throw new PersonNotFoundException(personId);
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuses an edit made from a version of the person other than the one stored now. */
public class CheckPersonVersion {
    public void check(@Val PersonRequest request, @Val Person person) throws StalePersonException {
        if (request.version() != null && request.version() != person.getVersion()) {
            throw new StalePersonException(String.valueOf(person.getId()));
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuses a person whose name another person on the sheet already has. */
public class CheckPersonName {
    public void check(@Val Person person, PersonRepository repository)
            throws DuplicatePersonNameException {
        if (repository.nameTaken(person.getSheetId(), person.getName(), person.getId())) {
            throw new DuplicatePersonNameException(person.getName());
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Applies the edit: the name, and the form's grade from its from-date (the sheet's today when blank),
 * keeping the grades already recorded. A grade left as the row showed it (the one in force on the
 * sheet's today) with the from-date blank records nothing. Their own terms become the form's, and
 * whether they differ from those the row showed is published for the audit.
 */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, @Val Sheet sheet, Out<TermsEdit> termsEdit) {
        person.setName(request.name());
        Integer terms = request.termsDays();
        termsEdit.set(new TermsEdit(!java.util.Objects.equals(terms, person.getTerms())));
        person.setTerms(terms);
        boolean dated = !request.gradeFrom().isEmpty();
        if (!dated && request.grade().equals(person.gradeOn(sheet.today()))) return;
        person.setGradeFrom(request.grade(), dated ? LocalDate.parse(request.gradeFrom()) : sheet.today());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonRepository repository) throws StalePersonException {
        if (!repository.save(person)) throw new StalePersonException(String.valueOf(person.getId()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved person, with the grade in force on the sheet's today, and their terms when the edit changed them. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditPersonEdited {
    public void audit(@Val Sheet sheet, @Val Person person, @Val TermsEdit termsEdit,
            HttpServletRequest request, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " name=" + person.getName() + " grade=" + person.gradeOn(sheet.today())
                + (termsEdit.changed() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : ""));
    }
}
package net.officefloor.hq.app.person;

/**
 * A person as the screen sends it, to add or to edit: a name, a grade (A, B or C) and the date the
 * grade is from (yyyy-MM-dd; blank for the sheet's today). An edit also names the version of the
 * person it was made from. Their own terms are a whole number of days, 0 or more (blank: none).
 */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms) {
    /** The terms as a number of days; null when blank. */
    public Integer termsDays() { return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms); }

    /** A person's name as the form takes it: trimmed, required, at most 200 characters. */
    public static String checkName(String raw) throws InvalidPersonException {
        String name = raw == null ? "" : raw.trim();
        if (name.isEmpty()) throw new InvalidPersonException("A name is required");
        if (name.length() > 200) throw new InvalidPersonException("A name is at most 200 characters");
        return name;
    }
}
package net.officefloor.hq.app.person;

/** Whether an edit changed the person's own terms from those the row showed before the save. */
public record TermsEdit(boolean changed) {}

